use vstd::prelude::*;

verus! {

spec fn elementwise_mod(a: Seq<u32>, b: Seq<u32>) -> Seq<u32>
    recommends a.len() == b.len()
{
    Seq::new(a.len(), |i: int| a[i] % b[i])
}

fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> (result: Vec<u32>)
    requires
        arr1@.len() == arr2@.len(),
        forall|i: int| 0 <= i < arr2@.len() ==> arr2@[i] != 0,
    ensures
        result@ == elementwise_mod(arr1@, arr2@),
{
    assert_eq!(arr1.len(), arr2.len(), "Input vectors must have the same length");

    let mut result = Vec::with_capacity(arr1.len());
    for (&a, &b) in arr1.iter().zip(arr2.iter())
        invariant
            arr1@.len() == arr2@.len(),
            forall|i: int| 0 <= i < arr2@.len() ==> arr2@[i] != 0,
            result@.len() <= arr1@.len(),
            // processed prefix correctness:
            forall|i: int|
                0 <= i < result@.len() ==> result@[i] == (arr1@[i] % arr2@[i]),
        ensures
            result@ == elementwise_mod(arr1@, arr2@),
    {
        assert!(b != 0, "Divisor elements must be non-zero");
        result.push(a % b);
    }
    result
}

} // verus!

